import os
"""Self-contained inspection of retained main-account trades and verified price frames."""
import json
from pathlib import Path
import pandas as pd
F=Path(__file__).resolve().parents[1];A=Path(os.environ.get('TPSA_R0_OUTPUT',str(F/'artifacts')));tr=pd.read_csv(A/'ML_p040/trades.csv');eq=pd.read_csv(A/'ML_p040/account_equity.csv');bars=pd.read_parquet(A/'verified_price_frames.parquet')
symbols=sorted(tr.symbol.unique());payload={'symbols':symbols,'trades':tr.where(tr.notna(),None).to_dict('records'),'equity':eq[['sequence','time','valuation_type','equity_ex_actual_funding']].to_dict('records'),'bars':{}}
for s in symbols:
 g=bars[bars.symbol.eq(s)].sort_values('ts');payload['bars'][s]=[[r.ts.isoformat(),r.open,r.high,r.low,r.close,bool(r.eligible)] for r in g.itertuples()]
assert len(tr)==json.loads((A/'ML_p040/metrics.json').read_text())['closed_trades'];assert not tr.event_id.duplicated().any();assert (pd.to_datetime(tr.entry_time,utc=True)<=pd.to_datetime(tr.exit_time,utc=True)).all()
for t in payload['trades']:
 dates={pd.Timestamp(b[0]) for b in payload['bars'][t['symbol']]};assert pd.Timestamp(t['entry_time']) in dates and pd.Timestamp(t['exit_time']) in dates
html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>TPSA-LA R0 交易路径核验</title><style>
body{font:15px system-ui;margin:24px;color:#222;background:#faf9f6}h1{font-size:24px}p{max-width:1100px;line-height:1.7}button,select{padding:8px;margin:5px;border:1px solid #bbb;background:white}canvas{width:100%;height:420px;background:white;border:1px solid #ddd;touch-action:none}#eq{height:190px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}tr:hover{background:#e6eff6;cursor:pointer}.note{color:#8a4521}#hover{height:25px;font:13px monospace}</style>
<h1>Binance-1D-TPSA-Long-Account · R0</h1><p class="note">冻结条件账本：$10,000，主模型 p ≥ 0.40，224 笔已平仓。旧 TPSA 特征 + V3 执行价；资金费未知，不能称净收益。日收盘与次日开盘同时间边界，成交属于理想价格代理，实际处理延迟/盘口未核准。无空头与强制反手。</p>
<label>标的 <select id="symbol"></select></label><button id="all">完整价格窗口</button><button id="prev">前移</button><button id="next">后移</button><span>滚轮缩放，拖动平移；点击交易表定位</span><div id="hover"></div><canvas id="price" width="1400" height="500"></canvas><p>红/绿 K 线为 V3 完整价格窗口；蓝线 MA7；蓝点入场、橙点出场与连接线。灰色 K 线表示不可用 bar，不填补缺失。</p><canvas id="eq" width="1400" height="230"></canvas><p>权益曲线含初始 $10,000；同一时间边界的日收盘与终端开盘平仓按 sequence 保留顺序。</p><table><thead><tr><th>标的/事件</th><th>入场 UTC</th><th>出场 UTC</th><th>数量</th><th>价格与手续费损益 USD</th><th>退出</th></tr></thead><tbody id="tbody"></tbody></table>
<script>const DATA=PAYLOAD;let symbol=DATA.symbols[0],lo=0,hi=0,drag=null;const c=document.getElementById('price'),ctx=c.getContext('2d'),select=document.getElementById('symbol');DATA.symbols.forEach(s=>{const o=document.createElement('option');o.textContent=s;select.append(o)});function num(x){return Number(x).toPrecision(6)}function reset(){lo=0;hi=DATA.bars[symbol].length-1;draw()}function draw(){const b=DATA.bars[symbol],v=b.slice(lo,hi+1),W=c.width,H=c.height,L=65,R=25,T=25,B=40;ctx.clearRect(0,0,W,H);if(!v.length)return;let mn=Math.min(...v.map(z=>z[3])),mx=Math.max(...v.map(z=>z[2]));const ts=DATA.trades.filter(t=>t.symbol===symbol);ts.forEach(t=>{mn=Math.min(mn,t.entry_price,t.exit_price);mx=Math.max(mx,t.entry_price,t.exit_price)});const x=i=>L+(i-lo)/(Math.max(hi-lo,1))*(W-L-R),y=p=>H-B-(p-mn)/(mx-mn||1)*(H-T-B);ctx.fillStyle='#222';ctx.font='15px system-ui';ctx.fillText(symbol+'  '+v[0][0].slice(0,10)+' → '+v.at(-1)[0].slice(0,10),L,18);for(let k=0;k<6;k++){let p=mn+(mx-mn)*k/5;ctx.strokeStyle='#eee';ctx.beginPath();ctx.moveTo(L,y(p));ctx.lineTo(W-R,y(p));ctx.stroke();ctx.fillText(num(p),2,y(p))}for(let i=lo;i<=hi;i++){let z=b[i],col=z[5]?(z[4]>=z[1]?'#29805c':'#b85146'):'#999';ctx.strokeStyle=col;ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(x(i),y(z[2]));ctx.lineTo(x(i),y(z[3]));ctx.stroke();let ww=Math.max(1,Math.min(10,(W-L-R)/(hi-lo+1)*.6));ctx.fillRect(x(i)-ww/2,Math.min(y(z[1]),y(z[4])),ww,Math.max(1,Math.abs(y(z[1])-y(z[4]))))}ctx.strokeStyle='#517ea8';ctx.beginPath();let begun=false;for(let i=Math.max(lo,6);i<=hi;i++){let vv=b.slice(i-6,i+1),continuous=vv.every((z,j)=>z[5]&&(!j||new Date(z[0])-new Date(vv[j-1][0])===86400000));if(!continuous){begun=false;continue}let m=vv.reduce((a,z)=>a+z[4],0)/7;if(begun)ctx.lineTo(x(i),y(m));else ctx.moveTo(x(i),y(m));begun=true}ctx.stroke();ts.forEach(t=>{let a=b.findIndex(z=>new Date(z[0]).getTime()===new Date(t.entry_time).getTime()),d=b.findIndex(z=>new Date(z[0]).getTime()===new Date(t.exit_time).getTime());if(a<lo||d>hi)return;ctx.strokeStyle='#b48754';ctx.beginPath();ctx.moveTo(x(a),y(t.entry_price));ctx.lineTo(x(d),y(t.exit_price));ctx.stroke();[[a,t.entry_price,'#195897'],[d,t.exit_price,'#d2762d']].forEach(([i,p,col])=>{ctx.fillStyle=col;ctx.beginPath();ctx.arc(x(i),y(p),4,0,7);ctx.fill()})});ctx.fillStyle='#222';ctx.fillText(v[0][0].slice(0,10),L,H-12);ctx.fillText(v.at(-1)[0].slice(0,10),W-120,H-12)}function bounds(){let n=DATA.bars[symbol].length;lo=Math.max(0,Math.min(lo,n-2));hi=Math.max(lo+1,Math.min(hi,n-1))}select.onchange=()=>{symbol=select.value;reset()};document.getElementById('all').onclick=reset;document.getElementById('prev').onclick=()=>{let s=Math.max(1,Math.floor((hi-lo)/4));lo-=s;hi-=s;bounds();draw()};document.getElementById('next').onclick=()=>{let s=Math.max(1,Math.floor((hi-lo)/4));lo+=s;hi+=s;bounds();draw()};c.onwheel=e=>{e.preventDefault();let n=hi-lo,m=(hi+lo)/2,f=e.deltaY>0?1.25:.8;n=Math.max(10,Math.min(DATA.bars[symbol].length-1,n*f));lo=Math.round(m-n/2);hi=Math.round(m+n/2);bounds();draw()};c.onpointerdown=e=>{drag=[e.offsetX,lo,hi];c.setPointerCapture(e.pointerId)};c.onpointerup=()=>drag=null;c.onpointermove=e=>{if(drag){let sh=Math.round((drag[0]-e.offsetX)/c.clientWidth*(drag[2]-drag[1]));lo=drag[1]+sh;hi=drag[2]+sh;bounds();draw()}let i=Math.round(lo+e.offsetX/c.clientWidth*(hi-lo)),b=DATA.bars[symbol][i];if(b)document.getElementById('hover').textContent=b[0]+' O '+num(b[1])+' H '+num(b[2])+' L '+num(b[3])+' C '+num(b[4])};DATA.trades.forEach(t=>{let r=document.createElement('tr');[t.event_id,t.entry_time,t.exit_time,num(t.qty),Number(t.price_fee_pnl).toFixed(2),t.exit_reason].forEach(x=>{let td=document.createElement('td');td.textContent=x;r.append(td)});r.onclick=()=>{symbol=t.symbol;select.value=symbol;let b=DATA.bars[symbol],a=b.findIndex(z=>new Date(z[0]).getTime()===new Date(t.entry_time).getTime()),d=b.findIndex(z=>new Date(z[0]).getTime()===new Date(t.exit_time).getTime());lo=a-20;hi=d+20;bounds();draw();c.scrollIntoView({behavior:'smooth'})};document.getElementById('tbody').append(r)});function equity(){let e=document.getElementById('eq'),q=e.getContext('2d'),v=[10000,...DATA.equity.map(z=>z.equity_ex_actual_funding)],mn=Math.min(...v),mx=Math.max(...v),W=e.width,H=e.height;q.fillStyle='#222';q.font='15px system-ui';q.fillText('Equity: $10,000 → $'+v.at(-1).toFixed(2)+' / actual funding excluded',20,20);q.strokeStyle='#195897';q.beginPath();v.forEach((z,i)=>{let x=65+i/(v.length-1)*(W-90),y=H-25-(z-mn)/(mx-mn)*(H-60);if(i)q.lineTo(x,y);else q.moveTo(x,y)});q.stroke()}reset();equity();</script></html>'''.replace('PAYLOAD',json.dumps(payload,separators=(',',':'),ensure_ascii=False).replace('</','<\\/'))
(A/'trade_paths.html').write_text(html)
(A/'trade_path_validation.json').write_text(json.dumps({'closed_trades':len(tr),'unique_event_ids':bool(not tr.event_id.duplicated().any()),'all_entry_not_after_exit':True,'both_endpoints_in_bar_path':True,'rendered_symbols':len(symbols),'retained_bar_rows':sum(map(len,payload['bars'].values())),'external_cdn':False,'template_placeholder_remaining':'PAYLOAD' in html},indent=2))
